    cell?: DataTableRootPassThroughType<React.HTMLAttributes<HTMLTableCellElement>>;
    /**
     * Used to pass attributes to the tfoot's DOM element.
     */
    foot?: DataTableRootPassThroughType<React.HTMLAttributes<HTMLTableSectionElement>>;
